bool dfs_(vector<vector<char>>& b, const string& w, int r, int c, int i) {
    if (i == (int)w.size()) return true; if (r < 0 || c < 0 || r >= (int)b.size() || c >= (int)b[0].size() || b[r][c] != w[i]) return false;
    char t = b[r][c]; b[r][c] = '#'; bool ok = dfs_(b, w, r+1, c, i+1) || dfs_(b, w, r-1, c, i+1) || dfs_(b, w, r, c+1, i+1) || dfs_(b, w, r, c-1, i+1); b[r][c] = t; return ok;
}
bool exist(vector<vector<char>>& b, string w) {
    map<char,int> have, need; for (auto& row : b) for (char ch : row) have[ch]++; for (char ch : w) need[ch]++;
    for (auto& [ch, k] : need) if (have[ch] < k) return false; if (have[w[0]] > have[w.back()]) reverse(w.begin(), w.end());
    for (int r = 0; r < (int)b.size(); r++) for (int c = 0; c < (int)b[0].size(); c++) if (dfs_(b, w, r, c, 0)) return true; return false;
}
